{"note":"Open-sided rear chassis: the disk closes the front, and the open sides give USB and wiring access without guessing a small port cutout. Check plug reach, wire slack and component height before printing. Black PLA is the available material; matte white requires white filament.","params":{"disk_d":{"value":242,"source":"measured"},"disk_t":{"value":1.56,"source":"measured"},"disk_hole":{"value":3.3,"source":"measured"},"inner_gap":{"value":30.2,"source":"measured"},"board_w":{"value":50,"source":"measured"},"board_l":{"value":70,"source":"measured"},"board_t":{"value":1.6,"source":"measured"},"board_hole":{"value":2.4,"source":"measured"},"edge_gap":{"value":0.9,"source":"measured"},"depth":{"value":42,"source":"design"},"usb_x":{"value":25,"source":"guessed"},"usb_y":{"value":0,"source":"guessed"},"usb_z":{"value":10,"source":"guessed"},"wall_head":{"value":8.5,"source":"catalog"},"wall_shank":{"value":5,"source":"catalog"},"wall_head_h":{"value":5,"source":"catalog"}},"parts":[{"id":"chassis","role":"final","material":"Black high-speed PLA","print_orientation":"Rear plate flat on bed","use_orientation":"Rear plate against wall, posts toward disk","code":"def build(p):
 w=p.board_w+26; l=p.board_l+24
