 def cyl(x,y,z,d,h):
  return cq.Workplane('XY').workplane(offset=z).center(x,y).circle(d/2).extrude(h)
 s=box(0,0,0,w,l,4)
 for x in (-23,23):
  s=s.union(box(x,40,4,16,14,7))
  d=p.wall_head+0.7; a=p.wall_shank+0.6
  s=s.cut(cyl(x,38,-1,d,13)).cut(box(x,41,-1,a,6,13)).cut(cyl(x,44,-1,a,13))
 for x in (-1,1):
  for y in (-1,1):
   u=x*(p.board_w/2-p.edge_gap-p.board_hole/2); v=y*(p.board_l/2-p.edge_gap-p.board_hole/2)
   s=s.union(cyl(u,v,4,8,6)).cut(cyl(u,v,5,1.65,6))
 # Separate front supports outside board footprint, with inward sloped corbels
 for sign in (-1,1):
  x=sign*(p.inner_gap+p.disk_hole)/2
  s=s.union(box(x,-42,4,14,10,p.depth-4))
  pts=[(-47,p.depth-39),(-37,p.depth-39),(7,p.depth-3),(7,p.depth),(-47,p.depth)]
  # slope starts at y=-37; use 45 degree or steeper from vertical
  pts=[(-47,p.depth-4),(-37,p.depth-4),(-37,4),( -35,4),(3,p.depth),( -47,p.depth)]
  # Ramp reaches y=3 at front, top hole centered at y=0
  ramp=cq.Workplane('YZ',origin=(x-7,0,0)).polyline([(-47,4),(-37,4),(1,p.depth),( -47,p.depth)]).close().extrude(14)
  # Move hole into a full-depth seat by extending slope from opposite board end
  ramp=cq.Workplane('YZ',origin=(x-7,0,0)).polyline([(-47,4),(-33,4),(5,p.depth),(-47,p.depth)]).close().extrude(14)
  s=s.union(ramp).cut(cyl(x,0,p.depth-4,4.3,4.1))
